    private static bool IsSupplyTruckOutOfReserves(UnitManager unit)
    {
        if (unit == null)
            return false;

        IReadOnlyList<UnitEmbarkedSupply> resources = unit.GetEmbarkedResources();
        if (resources == null || resources.Count <= 0)
            return true;

        bool hasCore = false;
        for (int i = 0; i < resources.Count; i++)
        {
            UnitEmbarkedSupply entry = resources[i];
            if (entry == null || entry.supply == null)
                continue;
            if (!IsCoreSupplyForTruck(entry.supply))
                continue;

            hasCore = true;
            if (entry.amount <= 0)
                return true;
        }

        if (hasCore)
            return false;

        // Fallback: sem mapeamento de supply core, considera vazio apenas quando TODOS estao zerados.
        bool hasAnyPositive = false;
        for (int i = 0; i < resources.Count; i++)
        {
            UnitEmbarkedSupply entry = resources[i];
            if (entry == null)
                continue;
            if (entry.amount > 0)
            {
                hasAnyPositive = true;
                break;
            }
        }

        return !hasAnyPositive;
    }

    private static bool IsCoreSupplyForTruck(SupplyData supply)
    {
        if (supply == null)
            return false;

        string id = !string.IsNullOrWhiteSpace(supply.id) ? supply.id : string.Empty;
        string name = !string.IsNullOrWhiteSpace(supply.displayName) ? supply.displayName : string.Empty;
        string text = (id + " " + name).ToLowerInvariant();

        return text.Contains("peca")
            || text.Contains("galao")
            || text.Contains("caixa");
    }

    private bool TryGetMostCriticalAllyForSupply(UnitManager supplier, AISnapshot snapshot, out UnitManager target)
    {
        target = null;
        if (supplier == null || snapshot == null)
            return false;

        // Prioridade 1: alvos validados pelo sensor (adjacentes/alcance valido agora).
        // Usa a mesma logica do botao S do jogador ? sem duplicacao de regras de alcance.
        if (turnStateManager != null)
        {
            var sensorOptions = new List<PodeSuprirOption>();
            if (turnStateManager.TryGetSupplyTargets(supplier, sensorOptions, out _) && sensorOptions.Count > 0)
            {
                int bestScore = int.MinValue;
                for (int i = 0; i < sensorOptions.Count; i++)
                {
                    UnitManager candidate = sensorOptions[i]?.targetUnit;
                    if (candidate == null || candidate.IsDead)
                        continue;
                    if (!IsSupplyTruckTargetThresholdMet(candidate, out int score))
                        continue;
                    if (score > bestScore)
                    {
                        bestScore = score;
                        target = candidate;
                    }
                }
                if (target != null)
                    return true;
            }
        }

        // Prioridade 2: objetivo de navegacao ? aliado mais critico no snapshot
        // (pode nao estar no alcance ainda; a unidade se movera ate ele).
        if (snapshot.FriendlyUnits == null)
            return false;

        Vector3Int supplierCell = supplier.CurrentCellPosition;
        supplierCell.z = 0;
        int navBestScore = int.MinValue;
        int navBestDistance = int.MaxValue;

        for (int i = 0; i < snapshot.FriendlyUnits.Count; i++)
        {
            UnitManager ally = snapshot.FriendlyUnits[i];
            if (ally == null || ally == supplier || ally.IsDead || ally.IsEmbarked)
                continue;
            if (!IsSupplyTruckTargetThresholdMet(ally, out int score))
                continue;

            Vector3Int allyCell = ally.CurrentCellPosition;
            allyCell.z = 0;
            int distance = GetHexDistance(snapshot.BoardTilemap, supplierCell, allyCell, 64);
            if (distance == int.MaxValue)
                distance = 64;

            bool better = score > navBestScore || (score == navBestScore && distance < navBestDistance);
            if (!better)
                continue;

            navBestScore = score;
            navBestDistance = distance;
            target = ally;
        }

        return target != null;
    }

    private static bool IsSupplyTruckTargetThresholdMet(UnitManager ally, out int score)
    {
        score = 0;
        if (ally == null || ally.IsDead)
            return false;

        bool lowHp = ally.CurrentHP <= 5;

        bool lowAmmo = false;
        int ammoCurrentTotal = 0;
        int ammoMaxTotal = 0;
        IReadOnlyList<UnitEmbarkedWeapon> runtimeWeapons = ally.GetEmbarkedWeapons();
        if (runtimeWeapons != null && runtimeWeapons.Count > 0)
        {
            if (ally.TryGetUnitData(out UnitData allyData) && allyData != null && allyData.embarkedWeapons != null)
            {
                int count = Mathf.Min(runtimeWeapons.Count, allyData.embarkedWeapons.Count);
                for (int i = 0; i < count; i++)
                {
                    UnitEmbarkedWeapon runtime = runtimeWeapons[i];
                    UnitEmbarkedWeapon baseline = allyData.embarkedWeapons[i];
                    if (runtime == null || baseline == null || baseline.weapon == null)
                        continue;

                    int maxAmmo = Mathf.Max(0, baseline.squadAmmunition);
                    if (maxAmmo <= 0)
                        continue;

                    ammoMaxTotal += maxAmmo;
                    ammoCurrentTotal += Mathf.Clamp(runtime.squadAmmunition, 0, maxAmmo);
                }
            }
        }

        if (ammoMaxTotal > 0)
            lowAmmo = (ammoCurrentTotal * 2) < ammoMaxTotal;

        if (!lowHp && !lowAmmo)
            return false;

        int hpMissing = Mathf.Max(0, ally.GetMaxHP() - ally.CurrentHP);
        int ammoMissing = Mathf.Max(0, ammoMaxTotal - ammoCurrentTotal);
        score = hpMissing * 120 + ammoMissing * 45 + (lowHp ? 5000 : 0) + (lowAmmo ? 3000 : 0);
        return true;
    }

    private bool TryGetSupplyTruckDefensivePatrolCell(UnitManager unit, AISnapshot snapshot, out Vector3Int targetCell)
    {
        targetCell = default;
        if (unit == null || snapshot == null || snapshot.BoardTilemap == null || !snapshot.HasHq)
            return false;

        Vector3Int unitCell = unit.CurrentCellPosition;
        unitCell.z = 0;
        Vector3Int hqCell = snapshot.HqCell;
        hqCell.z = 0;

        List<Vector3Int> frontier = new List<Vector3Int> { hqCell };
        HashSet<Vector3Int> visited = new HashSet<Vector3Int> { hqCell };
        List<Vector3Int> neighbors = new List<Vector3Int>(6);

        int bestDistToUnit = int.MaxValue;
        int bestDistToHq = int.MaxValue;
        Vector3Int best = default;
        bool found = false;

        for (int depth = 0; depth < 3; depth++)
        {
            List<Vector3Int> nextFrontier = new List<Vector3Int>();
            for (int i = 0; i < frontier.Count; i++)
            {
                Vector3Int current = frontier[i];
                UnitMovementPathRules.GetImmediateHexNeighbors(snapshot.BoardTilemap, current, neighbors);
                for (int n = 0; n < neighbors.Count; n++)
                {
                    Vector3Int cell = neighbors[n];
                    cell.z = 0;
                    if (visited.Contains(cell))
                        continue;
                    visited.Add(cell);
                    nextFrontier.Add(cell);

                    if (IsFriendlyConstructionCell(snapshot, unit.TeamId, cell))
                        continue;

                    int distToHq = GetHexDistance(snapshot.BoardTilemap, hqCell, cell, 32);
                    if (distToHq == int.MaxValue || distToHq <= 0 || distToHq > 2)
                        continue;

                    int distToUnit = GetHexDistance(snapshot.BoardTilemap, unitCell, cell, 64);
                    if (distToUnit == int.MaxValue)
                        continue;

                    bool better = !found
                        || distToUnit < bestDistToUnit
                        || (distToUnit == bestDistToUnit && distToHq < bestDistToHq);
                    if (!better)
                        continue;

                    found = true;
                    bestDistToUnit = distToUnit;
                    bestDistToHq = distToHq;
                    best = cell;
                }
            }

            frontier = nextFrontier;
            if (frontier.Count <= 0)
                break;
        }

        if (!found)
            return false;

        targetCell = best;
        targetCell.z = 0;
        return true;
    }

    private static bool IsFriendlyConstructionCell(AISnapshot snapshot, TeamId team, Vector3Int cell)
    {
        if (snapshot == null || snapshot.KnownConstructions == null)
            return false;

        cell.z = 0;
        for (int i = 0; i < snapshot.KnownConstructions.Count; i++)
        {
            AIConstructionInfo info = snapshot.KnownConstructions[i];
            if (info == null || info.Source == null)
                continue;
            if (info.TeamId != team)
                continue;

            Vector3Int c = info.Cell;
            c.z = 0;
            if (c == cell)
                return true;
        }

        return false;
    }

    private static bool IsFriendlyCaptureUnitOccupyingCell(AISnapshot snapshot, UnitManager requester, Vector3Int cell)
    {
        if (snapshot == null || requester == null || snapshot.FriendlyUnits == null)
            return false;

        cell.z = 0;
        for (int i = 0; i < snapshot.FriendlyUnits.Count; i++)
        {
            UnitManager ally = snapshot.FriendlyUnits[i];
            if (ally == null || ally == requester || ally.IsDead || ally.IsEmbarked)
                continue;
            if (ally.TeamId != requester.TeamId)
                continue;
            if (!(ally.TryGetUnitData(out UnitData allyData) && allyData != null
                && allyData.aiUnitProfile != null && allyData.aiUnitProfile.allowCapture
                && (allyData.aiUnitProfile.SensorPriority.Count == 0 || allyData.aiUnitProfile.SensorPriority[0] == AIUnitSensorKind.Capture)))
                continue;

            Vector3Int allyCell = ally.CurrentCellPosition;
            allyCell.z = 0;
            if (allyCell == cell)
                return true;
        }

        return false;
    }

    private static bool ShouldKeepUnitInRepairMode(UnitManager unit)
    {
        if (unit == null || unit.IsDead)
            return false;

        unit.TryGetUnitData(out UnitData data);
        AIUnitProfile profile = data?.aiUnitProfile;
        int enterThreshold = profile != null ? profile.hpRepairThreshold    : 3;
        int exitThreshold  = profile != null ? profile.hpRepairExitThreshold : 8;

        if (enterThreshold <= 0)
        {
            if (unit.AIForcedToRepair)
                unit.SetAIForcedToRepair(false);
            return false;
        }

        bool forced = unit.AIForcedToRepair;
        if (!forced && unit.CurrentHP <= enterThreshold)
            forced = true;
        if (forced && unit.CurrentHP >= exitThreshold)
            forced = false;

        if (unit.AIForcedToRepair != forced)
            unit.SetAIForcedToRepair(forced);

        return forced;
    }
    private static bool IsOutOfCombatAmmo(UnitManager unit)
    {
        if (unit == null)
            return false;

        IReadOnlyList<UnitEmbarkedWeapon> weapons = unit.GetEmbarkedWeapons();
        if (weapons == null || weapons.Count == 0)
            return false;

        bool hasAmmoBasedWeapon = false;
        for (int i = 0; i < weapons.Count; i++)
        {
            UnitEmbarkedWeapon w = weapons[i];
            if (w == null || w.weapon == null)
                continue;

            hasAmmoBasedWeapon = true;
            if (w.squadAmmunition > 0)
                return false;
        }

        return hasAmmoBasedWeapon;
    }

    private bool CanReachAndAttackThisTurn(
        UnitManager attacker,
        UnitManager enemy,
        AISnapshot snapshot,
        HashSet<Vector3Int> occupiedByAllies,
        Vector3Int attackerCell)
    {
        if (attacker == null || enemy == null || enemy.IsDead || snapshot == null || snapshot.BoardTilemap == null)
            return false;

        TerrainDatabase terrainDb = turnStateManager != null ? turnStateManager.TerrainDatabaseRef : null;
        int moveBudget = Mathf.Max(0, attacker.RemainingMovementPoints);
        Dictionary<Vector3Int, List<Vector3Int>> paths = UnitMovementPathRules.CalcularCaminhosValidos(
            snapshot.BoardTilemap,
            attacker,
            moveBudget,
            terrainDb);
        if (paths == null || paths.Count <= 0)
            return false;

        Vector3Int enemyCell = enemy.CurrentCellPosition;
        enemyCell.z = 0;
        attackerCell.z = 0;
        List<int> distances = new List<int>(8);
        return TryCollectReachableAttackDistances(
            snapshot.BoardTilemap,
            attacker,
            enemy,
            attackerCell,
            enemyCell,
            paths,
            occupiedByAllies,
            distances);
    }

    private bool TryGetBestRepairDislodgeTarget(
        UnitManager unit,
        AISnapshot snapshot,
        HashSet<Vector3Int> occupiedByAllies,
        Vector3Int unitCell,
        out UnitManager target,
        out string reason)
    {
        target = null;
        reason = string.Empty;

        if (unit == null || snapshot == null || snapshot.VisibleEnemies == null || snapshot.VisibleEnemies.Count <= 0)
            return false;
        if (!unit.TryGetUnitData(out UnitData attackerData) || attackerData == null)
            return false;

        RPSDatabase rpsDb = turnStateManager != null ? turnStateManager.RpsDatabaseRef : null;
        DPQMatchupDatabase dpqDb = turnStateManager != null ? turnStateManager.DpqMatchupDatabaseRef : null;
        WeaponPriorityData wpDb = turnStateManager != null ? turnStateManager.WeaponPriorityDataRef : null;
        if (rpsDb == null || dpqDb == null || wpDb == null)
            return false;

        int bestScore = int.MinValue;
        UnitManager best = null;

        for (int i = 0; i < snapshot.VisibleEnemies.Count; i++)
        {
            UnitManager enemy = snapshot.VisibleEnemies[i];
            if (enemy == null || enemy.IsDead)
                continue;
            if (!IsEnemyOccupyingOwnedConstructionForMyTeam(snapshot, unit, enemy))
                continue;
            if (!CanReachAndAttackThisTurn(unit, enemy, snapshot, occupiedByAllies, unitCell))
                continue;
            if (!enemy.TryGetUnitData(out UnitData defenderData) || defenderData == null)
                continue;

            Vector3Int enemyCell = enemy.CurrentCellPosition;
            enemyCell.z = 0;
            int rawDist = GetHexDistance(snapshot.BoardTilemap, unitCell, enemyCell, 64);
            if (rawDist == int.MaxValue)
                continue;

            List<int> reachableDistances = new List<int>(8);
            int moveBudget = Mathf.Max(0, unit.RemainingMovementPoints);
            Dictionary<Vector3Int, List<Vector3Int>> paths = UnitMovementPathRules.CalcularCaminhosValidos(
                snapshot.BoardTilemap,
                unit,
                moveBudget,
                turnStateManager != null ? turnStateManager.TerrainDatabaseRef : null);
            if (!TryCollectReachableAttackDistances(snapshot.BoardTilemap, unit, enemy, unitCell, enemyCell, paths, occupiedByAllies, reachableDistances))
                continue;

            int score = EvaluateAttackTargetScore(
                attackerData,
                defenderData,
                unit.CurrentHP,
                enemy.CurrentHP,
                rawDist,
                reachableDistances,
                currentStance == AIStance.Defend,
                rpsDb,
                dpqDb,
                wpDb,
                out _);

            if (score < 26000)
                continue;
            if (score <= bestScore)
                continue;

            bestScore = score;
            best = enemy;
        }

        if (best == null)
            return false;

        target = best;
        reason = "desocupar construcao propria para reparar";
        return true;
    }

    private bool TryGetRepairFallbackCell(
        UnitManager unit,
        AISnapshot snapshot,
        out Vector3Int targetCell,
        out string label)
    {
        targetCell = default;
        label = string.Empty;

        if (unit == null || snapshot == null)
            return false;

        if (snapshot.HasHq)
        {
            targetCell = snapshot.HqCell;
            targetCell.z = 0;
            label = "HQ (fallback defensivo)";
            return true;
        }

        targetCell = unit.CurrentCellPosition;
        targetCell.z = 0;
        label = "fallback local";
        return true;
    }

    private static bool IsEnemyOccupyingOwnedConstructionForMyTeam(AISnapshot snapshot, UnitManager attacker, UnitManager enemy)
    {
        if (snapshot == null || attacker == null || enemy == null)
            return false;

        return TryGetEnemyOccupyingOwnedConstruction(snapshot, attacker.TeamId, enemy.CurrentCellPosition, out _);
    }

    private static bool TryGetEnemyOccupyingOwnedConstruction(AISnapshot snapshot, TeamId myTeam, Vector3Int enemyCell, out AIConstructionInfo occupiedInfo)
    {
        occupiedInfo = null;
        if (snapshot == null || snapshot.KnownConstructions == null)
            return false;

        enemyCell.z = 0;
        for (int i = 0; i < snapshot.KnownConstructions.Count; i++)
        {
            AIConstructionInfo info = snapshot.KnownConstructions[i];
            if (info == null || info.Source == null)
                continue;

            Vector3Int constructionCell = info.Cell;
            constructionCell.z = 0;
            if (constructionCell != enemyCell)
                continue;
            if (!info.Source.IsCapturable || info.Source.CapturePointsMax <= 0)
                continue;
            if (info.TeamId != myTeam)
                continue;

            occupiedInfo = info;
            return true;
        }

        return false;
    }

    private bool TryGetNearestOwnedConstruction(
        UnitManager unit,
        AISnapshot snapshot,
        out ConstructionManager targetConstruction,
        out Vector3Int targetCell,
        out string targetLabel)
    {
        targetConstruction = null;
        targetCell = default;
        targetLabel = string.Empty;

        if (unit == null || snapshot == null || snapshot.KnownConstructions == null || snapshot.KnownConstructions.Count == 0)
            return false;

        TeamId myTeam = unit.TeamId;
        Vector3Int unitCell = unit.CurrentCellPosition;
        unitCell.z = 0;

        int bestDistance = int.MaxValue;
        AIConstructionInfo bestInfo = null;

        for (int i = 0; i < snapshot.KnownConstructions.Count; i++)
        {
            AIConstructionInfo info = snapshot.KnownConstructions[i];
            if (info == null || info.Source == null)
                continue;
            if (info.TeamId != myTeam)
                continue;
            if (TryGetBlockingShoppingOccupant(info.Source, out UnitManager blocker) && blocker != null && blocker != unit)
                continue;

            Vector3Int cell = info.Cell;
            cell.z = 0;
            int distance = GetHexDistance(snapshot.BoardTilemap, unitCell, cell, 64);
            if (distance == int.MaxValue)
                distance = 64;

            if (distance >= bestDistance)
                continue;

            bestDistance = distance;
            bestInfo = info;
        }

        if (bestInfo == null || bestInfo.Source == null)
            return false;

        targetConstruction = bestInfo.Source;
        targetCell = bestInfo.Cell;
        targetCell.z = 0;
        targetLabel = !string.IsNullOrWhiteSpace(bestInfo.DisplayName) ? bestInfo.DisplayName : bestInfo.Source.name;
        return true;
    }

    private bool TryEvaluateReachableAttackScore(
        UnitManager attacker,
        UnitManager enemy,
        AISnapshot snapshot,
        HashSet<Vector3Int> occupiedByAllies,
        out int score)
    {
        score = int.MinValue / 4;
        if (attacker == null || enemy == null || enemy.IsDead || snapshot == null || snapshot.BoardTilemap == null)
            return false;
        if (!attacker.TryGetUnitData(out UnitData attackerData) || attackerData == null)
            return false;
        if (!enemy.TryGetUnitData(out UnitData defenderData) || defenderData == null)
            return false;

        RPSDatabase rpsDb = turnStateManager != null ? turnStateManager.RpsDatabaseRef : null;
        DPQMatchupDatabase dpqDb = turnStateManager != null ? turnStateManager.DpqMatchupDatabaseRef : null;
        WeaponPriorityData wpDb = turnStateManager != null ? turnStateManager.WeaponPriorityDataRef : null;
        TerrainDatabase terrainDb = turnStateManager != null ? turnStateManager.TerrainDatabaseRef : null;
        if (rpsDb == null || dpqDb == null || wpDb == null)
            return false;

        int moveBudget = Mathf.Max(0, attacker.RemainingMovementPoints);
        Dictionary<Vector3Int, List<Vector3Int>> paths = UnitMovementPathRules.CalcularCaminhosValidos(
            snapshot.BoardTilemap,
            attacker,
            moveBudget,
            terrainDb);
        if (paths == null || paths.Count <= 0)
            return false;

        Vector3Int attackerCell = attacker.CurrentCellPosition;
        attackerCell.z = 0;
        Vector3Int enemyCell = enemy.CurrentCellPosition;
        enemyCell.z = 0;
        List<int> reachableAttackDistances = new List<int>(8);
        if (!TryCollectReachableAttackDistances(
                snapshot.BoardTilemap,
                attacker,
                enemy,
                attackerCell,
                enemyCell,
                paths,
                occupiedByAllies,
                reachableAttackDistances))
            return false;

        int tieDistance = GetHexDistance(snapshot.BoardTilemap, attackerCell, enemyCell, 64);
        if (tieDistance == int.MaxValue)
            tieDistance = 64;

        score = EvaluateAttackTargetScore(
            attackerData,
            defenderData,
            attacker.CurrentHP,
            enemy.CurrentHP,
            tieDistance,
            reachableAttackDistances,
            currentStance == AIStance.Defend,
            rpsDb,
            dpqDb,
            wpDb,
            out _);

        return score > (int.MinValue / 8);
    }

    private static bool IsEnemyInCaptureLane(
        Tilemap board,
        Vector3Int unitCell,
        Vector3Int captureObjectiveCell,
        Vector3Int enemyCell)
    {
        unitCell.z = 0;
        captureObjectiveCell.z = 0;
        enemyCell.z = 0;

        int unitToObjective = GetHexDistance(board, unitCell, captureObjectiveCell, 64);
        int enemyToObjective = GetHexDistance(board, enemyCell, captureObjectiveCell, 64);
        int unitToEnemy = GetHexDistance(board, unitCell, enemyCell, 64);
        if (unitToObjective == int.MaxValue || enemyToObjective == int.MaxValue || unitToEnemy == int.MaxValue)
            return false;

        if (enemyToObjective <= 1)
            return true;

        return unitToEnemy <= unitToObjective + 1 && enemyToObjective <= unitToObjective;
    }
    private bool IsEscortThreatRelevant(
        UnitManager escortUnit,
        UnitManager enemy,
        AISnapshot snapshot,
        AIPlanIntent intent,
        Vector3Int cohesionCell)
    {
        if (escortUnit == null || enemy == null || snapshot == null)
            return false;

        Vector3Int escortCell = escortUnit.CurrentCellPosition;
        escortCell.z = 0;
        Vector3Int enemyCell = enemy.CurrentCellPosition;
        enemyCell.z = 0;
        cohesionCell.z = 0;

        // Ameaca imediata para a propria escolta.
        int toEscort = GetHexDistance(snapshot.BoardTilemap, escortCell, enemyCell, 64);
        if (toEscort != int.MaxValue && toEscort <= 3)
            return true;

        // Ameaca no entorno do objetivo de coesao/captura do plano.
        int toCohesion = GetHexDistance(snapshot.BoardTilemap, cohesionCell, enemyCell, 64);
        if (toCohesion != int.MaxValue && toCohesion <= 4)
            return true;

        if (intent != null)
        {
            if (intent.HasCaptureTarget)
            {
                Vector3Int captureTarget = intent.CaptureTargetCell;
                captureTarget.z = 0;
                int toCaptureTarget = GetHexDistance(snapshot.BoardTilemap, captureTarget, enemyCell, 64);
                if (toCaptureTarget != int.MaxValue && toCaptureTarget <= 4)
                    return true;
            }

            if (intent.Assignments != null)
            {
                for (int i = 0; i < intent.Assignments.Count; i++)
                {
                    AIPlanAssignment asgn = intent.Assignments[i];
                    if (asgn == null || asgn.Role != AIPlanRole.Capture)
                        continue;

                    UnitManager captureUnit = FindUnitById(asgn.UnitInstanceId);
                    if (captureUnit != null && !captureUnit.IsDead)
                    {
                        Vector3Int captureCell = captureUnit.CurrentCellPosition;
                        captureCell.z = 0;
                        int toCaptureUnit = GetHexDistance(snapshot.BoardTilemap, captureCell, enemyCell, 64);
                        if (toCaptureUnit != int.MaxValue && toCaptureUnit <= 4)
                            return true;
                    }

                    if (asgn.HasPlannedCaptureTarget)
                    {
                        Vector3Int plannedCell = asgn.PlannedCaptureCell;
                        plannedCell.z = 0;
                        int toPlanned = GetHexDistance(snapshot.BoardTilemap, plannedCell, enemyCell, 64);
                        if (toPlanned != int.MaxValue && toPlanned <= 4)
                            return true;
                    }
                }
            }
        }

        return false;
    }


    private bool TryGetPlanCohesionObjective(
        UnitManager unit,
        AISnapshot snapshot,
        AIPlanIntent unitIntent,
        AIPlanAssignment unitAssignment,
        out Vector3Int targetCell,
        out string targetLabel)
    {
        targetCell = unit.CurrentCellPosition;
        targetCell.z = 0;
        targetLabel = unitIntent != null ? unitIntent.Sector.ToString() : "plano";

        if (unit == null || snapshot == null || unitIntent == null || unitAssignment == null)
            return false;
        if (unitIntent.Sector == ConstructionSector.BaseTeam)
            return false;

        Vector3Int unitCell = unit.CurrentCellPosition;
        unitCell.z = 0;
        int bestDistance = int.MaxValue;
        bool found = false;

        // Prioridade 1: escolta acompanha a unidade capturadora do mesmo plano.
        if (unitIntent.Assignments != null)
        {
            for (int i = 0; i < unitIntent.Assignments.Count; i++)
            {
                AIPlanAssignment asgn = unitIntent.Assignments[i];
                if (asgn == null || asgn.UnitInstanceId == unit.InstanceId)
                    continue;
                if (asgn.Role != AIPlanRole.Capture)
                    continue;

                UnitManager captureUnit = FindUnitById(asgn.UnitInstanceId);
                if (captureUnit == null || captureUnit.IsDead)
                    continue;

                Vector3Int candidate = captureUnit.CurrentCellPosition;
                candidate.z = 0;
                int dist = GetHexDistance(snapshot.BoardTilemap, unitCell, candidate, 64);
                if (dist == int.MaxValue) dist = 64;
                if (dist >= bestDistance) continue;

                bestDistance = dist;
                targetCell = candidate;
                targetLabel = captureUnit.name;
                found = true;
            }
        }

        if (found)
            return true;

        // Prioridade 2: objetivo de captura planejado para o setor.
        if (unitIntent.Assignments != null)
        {
            for (int i = 0; i < unitIntent.Assignments.Count; i++)
            {
                AIPlanAssignment asgn = unitIntent.Assignments[i];
                if (asgn == null || asgn.UnitInstanceId == unit.InstanceId)
                    continue;
                if (asgn.Role != AIPlanRole.Capture)
                    continue;

                Vector3Int candidate = asgn.HasPlannedCaptureTarget
                    ? asgn.PlannedCaptureCell
                    : (unitIntent.HasCaptureTarget ? unitIntent.CaptureTargetCell : unitCell);
                candidate.z = 0;
                int dist = GetHexDistance(snapshot.BoardTilemap, unitCell, candidate, 64);
                if (dist == int.MaxValue) dist = 64;
                if (dist >= bestDistance) continue;

                bestDistance = dist;
                targetCell = candidate;
                targetLabel = asgn.HasPlannedCaptureTarget && !string.IsNullOrWhiteSpace(asgn.PlannedCaptureLabel)
                    ? asgn.PlannedCaptureLabel
                    : unitIntent.Sector.ToString();
                found = true;
            }
        }

        if (found)
            return true;

        for (int i = 0; i < snapshot.KnownConstructions.Count; i++)
        {
            AIConstructionInfo info = snapshot.KnownConstructions[i];
            if (info == null || info.Sector != unitIntent.Sector || !info.IsCapturable)
                continue;

            bool aiOwnsFully = info.TeamId == unit.TeamId && info.CapturePoints >= info.CapturePointsMax;
            if (aiOwnsFully)
                continue;

            Vector3Int candidate = info.Cell;
            candidate.z = 0;
            int dist = GetHexDistance(snapshot.BoardTilemap, unitCell, candidate, 64);
            if (dist == int.MaxValue) dist = 64;
            if (dist >= bestDistance) continue;

            bestDistance = dist;
            targetCell = candidate;
            targetLabel = !string.IsNullOrWhiteSpace(info.DisplayName) ? info.DisplayName : unitIntent.Sector.ToString();
            found = true;
        }

        return found;
    }


    private bool TryGetBestCaptureObjectiveForInfantry(
        UnitManager unit,
        AISnapshot snapshot,
        out ConstructionManager targetConstruction,
        out Vector3Int targetCell,
        out string targetLabel,
        Vector3Int? plannedObjective = null,
        ConstructionSector? plannedSector = null)
    {
        targetConstruction = null;
        targetCell = default;
        targetLabel = string.Empty;

        if (unit == null || snapshot == null || snapshot.KnownConstructions == null || snapshot.KnownConstructions.Count == 0)
            return false;

        // Se o planner designou uma c?lula espec?fica, verifica se ainda ? v?lida/captur?vel e retorna ela.
        if (plannedObjective.HasValue)
        {
            Vector3Int planned = plannedObjective.Value;
            planned.z = 0;
            for (int i = 0; i < snapshot.KnownConstructions.Count; i++)
            {
                AIConstructionInfo info = snapshot.KnownConstructions[i];
                if (info == null || info.Source == null) continue;
                Vector3Int cell = info.Cell;
                cell.z = 0;
                if (cell != planned) continue;
                if (!info.IsCapturable || info.CapturePointsMax <= 0) break; // c?lula n?o captur?vel
                if (info.TeamId == unit.TeamId && info.CapturePoints >= info.CapturePointsMax) break; // j? nossa
                targetConstruction = info.Source;
                targetCell = cell;
                targetLabel = !string.IsNullOrWhiteSpace(info.DisplayName) ? info.DisplayName : info.Source.name;
                return true;
            }
            // Objetivo planejado inv?lido ? cai para sele??o normal
        }

        Vector3Int unitCell = unit.CurrentCellPosition;
        unitCell.z = 0;
        TeamId myTeam = unit.TeamId;

        int bestCategory = int.MaxValue;
        int bestDistance = int.MaxValue;
        AIConstructionInfo bestInfo = null;

        for (int i = 0; i < snapshot.KnownConstructions.Count; i++)
        {
            AIConstructionInfo info = snapshot.KnownConstructions[i];
            if (info == null || info.Source == null)
                continue;

            ConstructionManager construction = info.Source;
            if (plannedSector.HasValue && info.Sector != plannedSector.Value)
                continue;
            if (!construction.IsCapturable || construction.CapturePointsMax <= 0)
                continue;

            int category;
            if (info.TeamId == myTeam)
            {
                if (construction.CurrentCapturePoints >= construction.CapturePointsMax)
                    continue;
                category = 2;
            }
            else if (info.IsHq)
            {
                category = 0;
            }
            else
            {
                category = 1;
            }

            Vector3Int cell = info.Cell;
            cell.z = 0;
            int distance = GetHexDistance(snapshot.BoardTilemap, unitCell, cell, 64);
            if (distance == int.MaxValue)
                distance = 64;

            bool occupiedByOtherCaptureUnit = IsFriendlyCaptureUnitOccupyingCell(snapshot, unit, cell);
            int effectiveDistance = distance + (occupiedByOtherCaptureUnit ? 3 : 0);

            // Captura de infantaria: prioridade pratica = objetivo mais proximo.
            // Se ja existe outro aliado capturando esse mesmo hex, aplica penalidade para espalhar captura.
            // Categoria (HQ/outros/recuperacao) entra como desempate.
            bool better = effectiveDistance < bestDistance
                || (effectiveDistance == bestDistance && category < bestCategory);
            if (!better)
                continue;

            bestCategory = category;
            bestDistance = effectiveDistance;
            bestInfo = info;
        }

        if (bestInfo == null || bestInfo.Source == null)
            return false;

        targetConstruction = bestInfo.Source;
        targetCell = bestInfo.Cell;
        targetCell.z = 0;
        targetLabel = !string.IsNullOrWhiteSpace(bestInfo.DisplayName) ? bestInfo.DisplayName : bestInfo.Source.name;
        return true;
    }
    private IEnumerator Phase3_BuyUnits(TeamId aiTeam, AISnapshot snapshot)
    {
        if (turnStateManager == null)
        {
            if (aiLog) Debug.Log($"{T(aiTeam, 3)} TurnStateManager nao encontrado, pulando");
            yield break;
        }

        int bought = 0;
        for (int i = 0; i < snapshot.KnownConstructions.Count; i++)
        {
            AIConstructionInfo info = snapshot.KnownConstructions[i];
            if (info.TeamId != aiTeam || !info.CanProduceUnits || info.Source == null)
                continue;
            if (TryGetBlockingShoppingOccupant(info.Source, out UnitManager blocker))
            {
                if (aiLog)
                {
                    Debug.Log(
                        $"{T(aiTeam, 3)} sem compra planejada em {info.DisplayName} | " +
                        $"motivo: construcao bloqueada por {blocker.name} ({blocker.GetDomain()}/{blocker.GetHeightLevel()})");
                }
                continue;
            }

            yield return StartCoroutine(turnStateManager.WaitUntilAutomatedNeutralReady(2f));

            // Snapshot fresco para manter composicao/money/plano atualizados apos cada compra.
            AISnapshot current = TakeSnapshot(aiTeam);
            int currentMoney = matchController != null ? matchController.GetActualMoney(aiTeam) : 0;
            int incomePerTurn = matchController != null ? matchController.GetIncomePerTurn(aiTeam) : 0;

            if (!TryResolveShoppingPlan(aiTeam, current, info.Source, currentMoney, incomePerTurn, out int targetIndex, out string plannedUnitId, out string plannedReason))
            {
                if (aiLog) Debug.Log($"{T(aiTeam, 3)} sem compra planejada em {info.DisplayName} (saldo={currentMoney}) | motivo: {plannedReason}");
                continue;
            }

            Vector3Int cell = info.Source.CurrentCellPosition;
            cell.z = 0;

            // Fluxo replay-like: cursor vai para a construcao e abre shopping direto na construcao.
            // Evita colisao com unidade aliada ja agida estacionada no mesmo hex.
            yield return StartCoroutine(turnStateManager.MoveCursorToCellWithAutomatedTravel(cell));
            bool openedShopping = turnStateManager.TryAutomatedEnterShoppingAtConstruction(info.Source);

            float selectDelay = turnStateManager != null ? turnStateManager.GetAutomatedConfirmDelay() : (AnimationManager.Instance != null ? AnimationManager.Instance.AIUnitSelectDelay : 0.12f);
            float shoppingNavDelay = turnStateManager != null ? turnStateManager.GetAutomatedShoppingNavDelay() : selectDelay;
            yield return new WaitForSeconds(selectDelay);

            if (!openedShopping)
            {
                if (aiLog) Debug.Log($"{T(aiTeam, 3)} falha ao abrir shopping em {info.DisplayName}; pulando compra ({plannedUnitId}).");
                turnStateManager.HandleCancel();
                yield return StartCoroutine(turnStateManager.WaitUntilAutomatedNeutralReady(2f));
                continue;
            }

            int guard = 0;
            const int maxGuard = 256;
            while (turnStateManager.CurrentCursorState == TurnStateManager.CursorState.ShoppingAndServices)
            {
                int currentIndex = turnStateManager.GetShoppingSelectedIndexForReplay();
                if (currentIndex >= targetIndex)
                    break;

                if (guard++ >= maxGuard)
                {
                    if (aiLog) Debug.Log($"{T(aiTeam, 3)} guarda de navegacao atingida (targetIndex={targetIndex})");
                    break;
                }

                bool moved = turnStateManager.TryResolveShoppingCursorMoveForReplay(Vector3Int.right);
                if (!moved)
                    moved = turnStateManager.TryResolveShoppingCursorMoveForReplay(new Vector3Int(0, -1, 0));
                if (!moved)
                {
                    if (aiLog) Debug.Log($"{T(aiTeam, 3)} falha ao navegar catalogo (current={currentIndex}, target={targetIndex})");
                    break;
                }

                if (shoppingNavDelay > 0f)
                    yield return new WaitForSeconds(shoppingNavDelay);
                yield return null;
            }

            bool success = turnStateManager.TryConfirmSelectedShoppingOptionForReplay();
            string posturaLabel = currentStance == AIStance.Defend ? "defesa" : "ataque";
            if (aiLog) Debug.Log($"{T(aiTeam, 3)} compra em {info.DisplayName}: {(success ? "OK" : "falhou")} ({plannedUnitId}) | motivo: {plannedReason} | postura: {posturaLabel}");
            if (success)
            {
                bought++;
            }

            yield return StartCoroutine(turnStateManager.WaitUntilAutomatedNeutralReady(2f));
        }

        if (aiLog) Debug.Log($"{T(aiTeam, 3)} total comprado: {bought}");
    }

    private static bool TryGetBlockingShoppingOccupant(ConstructionManager construction, out UnitManager blockingUnit)
    {
        blockingUnit = null;
        if (construction == null)
            return false;

        Vector3Int constructionCell = construction.CurrentCellPosition;
        constructionCell.z = 0;

        for (int i = 0; i < UnitManager.AllActive.Count; i++)
        {
            UnitManager unit = UnitManager.AllActive[i];
            if (unit == null || unit.IsDead || unit.IsEmbarked || !unit.gameObject.activeInHierarchy)
                continue;

            Vector3Int unitCell = unit.CurrentCellPosition;
            unitCell.z = 0;
            if (unitCell != constructionCell)
                continue;
            if (!IsBlockingUnitForConstructionShopping(unit))
                continue;

            blockingUnit = unit;
            return true;
        }

        return false;
    }

    private static bool IsBlockingUnitForConstructionShopping(UnitManager unit)
    {
        if (unit == null)
            return false;

        Domain domain = unit.GetDomain();
        HeightLevel height = unit.GetHeightLevel();
        if (height != HeightLevel.Surface)
            return false;

        // Regras pedidas: bloqueiam o hex para compra em construcao.
        return domain == Domain.Land || domain == Domain.Naval;
    }

    private bool TryResolveShoppingPlan(
        TeamId aiTeam,
        AISnapshot snapshot,
        ConstructionManager construction,
        int currentMoney,
        int incomePerTurn,
        out int targetIndex,
        out string plannedUnitId,
        out string plannedReason)
    {
        targetIndex = -1;
        plannedUnitId = null;
        plannedReason = "nenhum";

        if (construction == null)
        {
            plannedReason = "construcao invalida";
            return false;
        }

        AIData effectiveData = GetEffectiveAIData(aiTeam);
        AIDataMode mode = currentStance == AIStance.Defend
            ? effectiveData.defenseMode
            : effectiveData.attackMode;

        return TryResolveShoppingPlanFromMode(snapshot, construction, currentMoney, incomePerTurn, mode, out targetIndex, out plannedUnitId, out plannedReason);
    }

    private bool TryResolveShoppingPlanFromMode(
        AISnapshot snapshot,
        ConstructionManager construction,
        int currentMoney,
        int incomePerTurn,
        AIDataMode mode,
        out int targetIndex,
        out string plannedUnitId,
        out string plannedReason)
    {
        targetIndex = -1;
        plannedUnitId = null;
        plannedReason = "nenhum";

        if (mode == null || mode.groups == null || mode.groups.Count == 0)
        {
            plannedReason = "modo sem grupos configurados";
            return false;
        }

        List<AIDataGroup> orderedGroups = GetGroupsByPriority(mode.groups);
        Dictionary<AIDataGroup, int> countsByGroup = CountFriendlyUnitsByConfiguredGroup(snapshot, orderedGroups);
        int totalUnits = snapshot != null && snapshot.FriendlyUnits != null ? snapshot.FriendlyUnits.Count : 0;
        int denominator = Mathf.Max(1, totalUnits);
        int missingCapturePlans = CountPlansMissingCaptureRole(snapshot);

        // Urgencia de abertura: se existem planos de captura sem capturador, prioriza
        // comprar qualquer unidade com perfil allowCapture=true antes da composicao percentual.
        if (missingCapturePlans > 0 &&
            TryResolveFirstAffordableCaptureCapableFromGroups(construction, orderedGroups, currentMoney, out targetIndex, out plannedUnitId))
        {
            plannedReason = $"urgencia-captura | planos-sem-capturador={missingCapturePlans}";
            return true;
        }

        for (int i = 0; i < orderedGroups.Count; i++)
        {
            AIDataGroup group = orderedGroups[i];
            if (group == null)
                continue;

            float targetRatio = Mathf.Clamp01(group.targetPercentage / 100f);
            int currentCount = countsByGroup.TryGetValue(group, out int value) ? value : 0;
            float currentRatio = Mathf.Clamp01((float)currentCount / denominator);

            if (currentRatio + 0.0001f >= targetRatio)
                continue;

            if (TryResolveFirstAffordableFromGroup(construction, group, currentMoney, out targetIndex, out plannedUnitId))
            {
                plannedReason = $"grupo={group.label} | composicao={currentCount}/{denominator} ({currentRatio:P0}) | alvo={targetRatio:P0} | prioridade={group.priority}";
                return true;
            }

            if (mode.saveForNextRound)
            {
                if (mode.allowFallbackWhenSaving &&
                    TryResolveFirstAffordableFromUnitList(construction, mode.fallbackUnits, currentMoney, out targetIndex, out plannedUnitId))
                {
                    plannedReason = $"fallback-save | modo={mode.label} | motivo=guardando para composicao de grupo {group.label}";
                    return true;
                }

                plannedReason = $"economizou para proxima rodada | grupo pendente={group.label} | composicao={currentCount}/{denominator} ({currentRatio:P0}) | alvo={targetRatio:P0}";
                return false;
            }
        }

        // Se todas as metas ja foram atendidas (ou nao havia compra possivel na meta),
        // compra pela ordem de prioridade/lista configurada.
        for (int i = 0; i < orderedGroups.Count; i++)
        {
            AIDataGroup group = orderedGroups[i];
            if (group == null)
                continue;

            if (TryResolveFirstAffordableFromGroup(construction, group, currentMoney, out targetIndex, out plannedUnitId))
            {
                int currentCount = countsByGroup.TryGetValue(group, out int value) ? value : 0;
                float currentRatio = Mathf.Clamp01((float)currentCount / denominator);
                float targetRatio = Mathf.Clamp01(group.targetPercentage / 100f);
                plannedReason = $"grupo-prioridade={group.label} | composicao={currentCount}/{denominator} ({currentRatio:P0}) | alvo={targetRatio:P0} | prioridade={group.priority}";
                return true;
            }
        }

        // Sem nada acessivel nos grupos: tenta fallback de contingencia configurado no modo.
        if (TryResolveFirstAffordableFromUnitList(construction, mode.fallbackUnits, currentMoney, out targetIndex, out plannedUnitId))
        {
            plannedReason = $"fallback-modo={mode.label} | motivo=sem oferta acessivel nos grupos";
            return true;
        }

        // Sem nada acessivel agora: opcionalmente poupa para o proximo turno.
        if (mode.saveForNextRound)
        {
            plannedReason = "economizou para proxima rodada | sem ofertas acessiveis nos grupos/fallback";
            return false;
        }

        // Fallback final: tenta qualquer oferta acessivel no catalogo.
        if (TryResolveAnyAffordableOffer(construction, currentMoney, out targetIndex, out plannedUnitId))
        {
            plannedReason = "fallback-catalogo | motivo=qualquer oferta acessivel";
            return true;
        }

        plannedReason = "nenhuma oferta acessivel no catalogo";
        return false;
    }

    private static int CountPlansMissingCaptureRole(AISnapshot snapshot)
    {
        if (snapshot == null || snapshot.ActivePlans == null || snapshot.ActivePlans.Count == 0)
            return 0;

        int missing = 0;
        for (int i = 0; i < snapshot.ActivePlans.Count; i++)
        {
            AIPlanIntent intent = snapshot.ActivePlans[i];
            if (intent == null || !intent.HasCaptureTarget || intent.Sector == ConstructionSector.BaseTeam)
                continue;

            bool hasCapture = false;
            if (intent.Assignments != null)
            {
                for (int a = 0; a < intent.Assignments.Count; a++)
                {
                    AIPlanAssignment assignment = intent.Assignments[a];
                    if (assignment != null && assignment.Role == AIPlanRole.Capture)
                    {
                        hasCapture = true;
                        break;
                    }
                }
            }

            if (!hasCapture)
                missing++;
        }

        return missing;
    }

    private static bool TryResolveFirstAffordableCaptureCapableFromGroups(
        ConstructionManager construction,
        IReadOnlyList<AIDataGroup> orderedGroups,
        int currentMoney,
        out int targetIndex,
        out string plannedUnitId)
    {
        targetIndex = -1;
        plannedUnitId = null;

        if (construction == null || orderedGroups == null)
            return false;

        for (int g = 0; g < orderedGroups.Count; g++)
        {
            AIDataGroup group = orderedGroups[g];
            if (group == null || group.specificUnits == null || group.specificUnits.Count == 0)
                continue;

            for (int i = 0; i < group.specificUnits.Count; i++)
            {
                UnitData wantedUnit = group.specificUnits[i];
                if (wantedUnit == null || string.IsNullOrWhiteSpace(wantedUnit.id))
                    continue;
                if (wantedUnit.aiUnitProfile == null || !wantedUnit.aiUnitProfile.allowCapture)
                    continue;

                if (!TryGetAffordableOfferIndex(construction, wantedUnit, currentMoney, out int index, out UnitData offer))
                    continue;

                targetIndex = index;
                plannedUnitId = offer != null ? offer.id : wantedUnit.id;
                return true;
            }
        }

        return false;
    }
    private static List<AIDataGroup> GetGroupsByPriority(List<AIDataGroup> groups)
    {
        List<AIDataGroup> ordered = new List<AIDataGroup>();
        for (int i = 0; i < groups.Count; i++)
        {
            if (groups[i] != null)
                ordered.Add(groups[i]);
        }

        ordered.Sort((a, b) =>
        {
            int pa = a != null ? a.priority : int.MaxValue;
            int pb = b != null ? b.priority : int.MaxValue;
            int cmp = pa.CompareTo(pb);
            if (cmp != 0)
                return cmp;

            string la = a != null ? a.label : string.Empty;
            string lb = b != null ? b.label : string.Empty;
            return string.CompareOrdinal(la, lb);
        });

        return ordered;
    }

    private static Dictionary<AIDataGroup, int> CountFriendlyUnitsByConfiguredGroup(AISnapshot snapshot, List<AIDataGroup> orderedGroups)
    {
        Dictionary<AIDataGroup, int> counts = new Dictionary<AIDataGroup, int>();
        if (orderedGroups == null)
            return counts;

        for (int i = 0; i < orderedGroups.Count; i++)
            counts[orderedGroups[i]] = 0;

        if (snapshot == null || snapshot.FriendlyUnits == null)
            return counts;

        for (int i = 0; i < snapshot.FriendlyUnits.Count; i++)
        {
            UnitManager unit = snapshot.FriendlyUnits[i];
            if (unit == null || unit.IsDead || string.IsNullOrWhiteSpace(unit.UnitId))
                continue;

            for (int g = 0; g < orderedGroups.Count; g++)
            {
                AIDataGroup group = orderedGroups[g];
                if (group == null || group.specificUnits == null || group.specificUnits.Count == 0)
                    continue;

                if (!GroupContainsUnitId(group, unit.UnitId))
                    continue;

                counts[group] = counts[group] + 1;
                break;
            }
        }

        return counts;
    }

    private static bool GroupContainsUnitId(AIDataGroup group, string unitId)
    {
        if (group == null || group.specificUnits == null || string.IsNullOrWhiteSpace(unitId))
            return false;

        for (int i = 0; i < group.specificUnits.Count; i++)
        {
            UnitData candidate = group.specificUnits[i];
            if (candidate == null || string.IsNullOrWhiteSpace(candidate.id))
                continue;

            if (string.Equals(candidate.id, unitId, System.StringComparison.OrdinalIgnoreCase))
                return true;
        }

        return false;
    }

    private static bool TryResolveFirstAffordableFromGroup(
        ConstructionManager construction,
        AIDataGroup group,
        int currentMoney,
        out int targetIndex,
        out string plannedUnitId)
    {
        targetIndex = -1;
        plannedUnitId = null;

        if (construction == null || group == null || group.specificUnits == null)
            return false;

        for (int i = 0; i < group.specificUnits.Count; i++)
        {
            UnitData wantedUnit = group.specificUnits[i];
            if (wantedUnit == null || string.IsNullOrWhiteSpace(wantedUnit.id))
                continue;

            if (!TryGetAffordableOfferIndex(construction, wantedUnit, currentMoney, out int index, out UnitData offer))
                continue;

            targetIndex = index;
            plannedUnitId = offer != null ? offer.id : wantedUnit.id;
            return true;
        }

        return false;
    }

    private static bool TryResolveFirstAffordableFromUnitList(
        ConstructionManager construction,
        IReadOnlyList<UnitData> fallbackUnits,
        int currentMoney,
        out int targetIndex,
        out string plannedUnitId)
    {
        targetIndex = -1;
        plannedUnitId = null;

        if (construction == null || fallbackUnits == null)
            return false;

        for (int i = 0; i < fallbackUnits.Count; i++)
        {
            UnitData wantedUnit = fallbackUnits[i];
            if (wantedUnit == null || string.IsNullOrWhiteSpace(wantedUnit.id))
                continue;

            if (!TryGetAffordableOfferIndex(construction, wantedUnit, currentMoney, out int index, out UnitData offer))
                continue;

            targetIndex = index;
            plannedUnitId = offer != null ? offer.id : wantedUnit.id;
            return true;
        }

        return false;
    }

    private static bool TryResolveAnyAffordableOffer(
        ConstructionManager construction,
        int currentMoney,
        out int targetIndex,
        out string plannedUnitId)
    {
        targetIndex = -1;
        plannedUnitId = null;

        if (construction == null)
            return false;

        IReadOnlyList<UnitData> offered = construction.OfferedUnits;
        if (offered == null)
            return false;

        for (int i = 0; i < offered.Count; i++)
        {
            UnitData unit = offered[i];
            if (unit == null)
                continue;

            int cost = Mathf.Max(0, unit.cost);
            if (cost > currentMoney)
                continue;

            targetIndex = i;
            plannedUnitId = unit.id;
            return true;
        }

        return false;
    }

    private static bool TryGetAffordableOfferIndex(ConstructionManager construction, UnitData wantedUnit, int currentMoney, out int index, out UnitData offer)
    {
        index = -1;
        offer = null;
        if (!TryGetOfferIndex(construction, wantedUnit, out int found, out UnitData unit) || unit == null)
            return false;

        int cost = Mathf.Max(0, unit.cost);
        if (currentMoney < cost)
            return false;

        index = found;
        offer = unit;
        return true;
    }

    private static bool TryGetOfferIndex(ConstructionManager construction, UnitData wantedUnit, out int index, out UnitData offer)
    {
        index = -1;
        offer = null;

        if (construction == null || wantedUnit == null)
            return false;

        IReadOnlyList<UnitData> offered = construction.OfferedUnits;
        if (offered == null || offered.Count == 0)
            return false;

        string wantedId = wantedUnit.id;
        for (int i = 0; i < offered.Count; i++)
        {
            UnitData unit = offered[i];
            if (unit == null)
                continue;

            if (ReferenceEquals(unit, wantedUnit))
            {
                index = i;
                offer = unit;
                return true;
            }

            if (!string.IsNullOrWhiteSpace(wantedId) && !string.IsNullOrWhiteSpace(unit.id)
                && string.Equals(unit.id, wantedId, System.StringComparison.OrdinalIgnoreCase))
            {
                index = i;
                offer = unit;
                return true;
            }
        }

        return false;
    }
    private static bool TryGetPreferredEngagementRangeForTarget(UnitManager attacker, UnitManager target, out int minRange, out int maxRange)
    {
        minRange = 1;
        maxRange = 1;
        if (attacker == null || target == null)
            return false;

        Domain targetDomain = target.GetDomain();
        HeightLevel targetHeight = target.GetHeightLevel();
        IReadOnlyList<UnitEmbarkedWeapon> weapons = attacker.GetEmbarkedWeapons();
        if (weapons == null || weapons.Count == 0)
            return false;

        int resolvedMin = int.MaxValue;
        int resolvedMax = int.MinValue;
        bool found = false;

        for (int i = 0; i < weapons.Count; i++)
        {
            UnitEmbarkedWeapon embarked = weapons[i];
            if (embarked == null || embarked.weapon == null)
                continue;
            if (embarked.squadAmmunition <= 0)
                continue;
            if (!embarked.weapon.SupportsOperationOn(targetDomain, targetHeight))
                continue;
            if (!PodeMirarSensor.TryResolveWeaponRangeCandidate(
                    embarked,
                    SensorMovementMode.MoveuParado,
                    requireAmmo: true,
                    out int wMin,
                    out int wMax))
                continue;

            found = true;
            if (wMin < resolvedMin)
                resolvedMin = wMin;
            if (wMax > resolvedMax)
                resolvedMax = wMax;
        }

        if (!found)
            return false;

        minRange = Mathf.Max(1, resolvedMin);
        maxRange = Mathf.Max(minRange, resolvedMax);
        return true;
    }
    private static bool TryGetPreferredArtilleryRange(UnitManager unit, out int minRange, out int maxRange)
    {
        minRange = 1;
        maxRange = 1;
        if (unit == null)
            return false;

        IReadOnlyList<UnitEmbarkedWeapon> weapons = unit.GetEmbarkedWeapons();
        if (weapons == null || weapons.Count == 0)
            return false;

        Domain domain = unit.GetDomain();
        HeightLevel height = unit.GetHeightLevel();
        int bestMax = int.MinValue;
        bool found = false;

        for (int i = 0; i < weapons.Count; i++)
        {
            UnitEmbarkedWeapon weapon = weapons[i];
            if (weapon == null)
                continue;
            if (weapon.squadAmmunition <= 0)
                continue;
            if (!weapon.CanFireAtLayer(domain, height))
                continue;

            int wMin = weapon.GetRangeMin();
            int wMax = weapon.GetRangeMax();
            if (wMin <= 1)
                continue;

            if (!found || wMax > bestMax)
            {
                found = true;
                bestMax = wMax;
                minRange = wMin;
                maxRange = wMax;
            }
        }

        return found;
    }

    private void Phase4_EndTurn(TeamId aiTeam)
    {
        if (aiLog) Debug.Log($"{T(aiTeam, 4)} Passando a vez");
        matchController.AdvanceTurnWithTransition();
    }

